    var originRef = 'origin/' + (baseBranch || 'main');
    try {
        var log = cleanCommandOutput(runCmd({ command: 'git log ' + originRef + '..HEAD --oneline' }) || '');
        if (log.trim()) return true;
    } catch (e) {
